    // ---------- whole level with the trail-following autopilot ----------
    const run = await page.evaluate(([fps, speed, glow, stillsWanted]) => {
      const dt = 1 / fps, rows = [], ov = [], ovPop = [], pickups = []; let i = 0, doneAt = null, prevCoins = window.state().coins;
